<?php
require_once __DIR__.'/../app/bootstrap.php'; require_admin(); ensure_feedback_schema(); ensure_donations_schema();
$q=trim((string)($_GET['q']??''));$status=in_array($_GET['status']??'', ['pending','active','blocked'],true)?$_GET['status']:'';$page=max(1,(int)($_GET['page']??1));$perPage=30;$where=[];$args=[];
if($q!==''){$where[]='(u.username LIKE ? OR u.email LIKE ? OR p.display_name LIKE ? OR p.business_local LIKE ?)';$like='%'.$q.'%';array_push($args,$like,$like,$like,$like);}if($status!==''){$where[]='u.status=?';$args[]=$status;}$ws=$where?' WHERE '.implode(' AND ',$where):'';
$ct=db()->prepare("SELECT COUNT(*) FROM users u LEFT JOIN profiles p ON p.user_id=u.id{$ws}");$ct->execute($args);$total=(int)$ct->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$st=db()->prepare("SELECT u.*,p.display_name,p.business_local,p.whatsapp,(SELECT COUNT(*) FROM products pr WHERE pr.user_id=u.id) product_count,(SELECT COALESCE(SUM(d.amount_clp),0) FROM donations d WHERE d.seller_id=u.id AND d.status='verified' AND DATE_FORMAT(d.donated_at,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')) donation_month FROM users u LEFT JOIN profiles p ON p.user_id=u.id{$ws} ORDER BY u.created_at DESC LIMIT {$perPage} OFFSET {$offset}");$st->execute($args);$users=$st->fetchAll();
$adminPage='users';$adminTitle='Usuarios';$adminSubtitle='Editar, aprobar, bloquear, vaciar contenido o eliminar cuentas de forma segura';require __DIR__.'/partials/header.php';
?>
<section class="panel-card mt-0"><div class="panel-head"><div><h2>👥 Usuarios registrados</h2><p><?=$total?> cuentas · página <?=$page?> de <?=$pages?> · la cuenta actual y el último administrador están protegidos</p></div></div><form method="get" class="admin-filterbar admin-filterbar-pro"><input class="admin-search" name="q" value="<?=e($q)?>" placeholder="Buscar nombre, usuario, correo o negocio..."><select name="status"><option value="">Todos los estados</option><?php foreach(['pending','active','blocked'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=$s?></option><?php endforeach;?></select><button class="admin-btn">🔎 Filtrar</button><a class="admin-btn secondary" href="users.php">Limpiar</a></form>
<div class="admin-table-wrap mt-20"><table class="admin-table"><thead><tr><th>Usuario</th><th>Negocio</th><th>Contenido</th><th>Aporte del mes</th><th>Rol / estado</th><th>Administrar</th></tr></thead><tbody>
<?php foreach($users as $u):$donOk=(int)$u['donation_month']>=donation_minimum();?><tr><td><b><?=e($u['display_name']?:$u['username'])?></b><small>@<?=e($u['username'])?> · <?=e($u['email'])?></small><small>Desde <?=e(date('d/m/Y',strtotime($u['created_at'])))?></small></td><td><?=e($u['business_local']?:'Sin local')?><small><?=e($u['whatsapp']?:'Sin WhatsApp')?></small></td><td><b><?=number_format((int)$u['product_count'])?></b> artículos</td><td><span class="status <?=$donOk?'active':'pending'?>"><?=money_clp((int)$u['donation_month'])?></span><small>Meta: <?=money_clp(donation_minimum())?></small></td><td><span class="status <?=e($u['status'])?>"><?=e($u['status'])?></span><small><?=e($u['role']==='admin'?'Administrador':'Vendedor')?></small></td><td><div class="table-actions"><a class="admin-btn small" href="user_edit.php?id=<?=$u['id']?>">✏️ Editar</a><?php if((int)$u['id']!==(int)user()['id']):?><a class="admin-btn small danger" href="user_delete.php?id=<?=$u['id']?>">🗑️ Vaciar / eliminar</a><?php else:?><small>Cuenta actual protegida</small><?php endif;?></div></td></tr><?php endforeach;?><?php if(!$users):?><tr><td colspan="6"><div class="empty-admin">No se encontraron usuarios.</div></td></tr><?php endif;?></tbody></table></div><?=admin_pagination($page,$pages,$_GET)?></section>
<?php require __DIR__.'/partials/footer.php';?>
